const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const ANON = String((entrada0 => (entrada0.headers || {}).apikey || '')($('Webhook').first().json));
const entrada = $('Webhook').first().json;
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
if (!jwt || !/^[0-9a-f-]{36}$/i.test(String(avaliacaoId || ''))) throw new Error('Pedido inválido.');
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const user = await req({ method: 'GET', url: SB + '/auth/v1/user' });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });

try {
  const [av] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=id,edital_path,modulo' });
  if (!av) throw new Error('Avaliação não encontrada ou sem acesso.');
  if (!av.edital_path) throw new Error('Envie o edital ou a matrícula (PDF) antes de pedir a leitura.');
  await patch({ etapa: 'lendo_edital', etapa_erro: null });
  const buf = await this.helpers.httpRequest({ method: 'GET', url: SB + '/storage/v1/object/editais/' + av.edital_path, headers: H, encoding: 'arraybuffer', json: false });
  const b64 = Buffer.from(buf).toString('base64');
  if (b64.length < 1000) throw new Error('O arquivo enviado está vazio ou corrompido.');
  const ehPdf = av.edital_path.toLowerCase().endsWith('.pdf');
  const campos = { endereco: 'string', numero: 'string', unidade: 'string', condominio: 'string', bairro: 'string', cidade: 'string', uf: 'string', cep: 'string',
    tipo_imovel: 'string', area_privativa_m2: 'number', area_comum_m2: 'number', area_total_m2: 'number', area_terreno_m2: 'number', area_construida_m2: 'number', fracao_ideal: 'number',
    dormitorios: 'integer', vagas: 'integer', andar: 'string', lote_quadra: 'string', testada_m: 'number', numero_matricula: 'string', cartorio_registro: 'string', cnm: 'string', contribuinte_iptu: 'string',
    numero_processo: 'string', tribunal_vara: 'string', exequente: 'string', avaliacao_judicial_valor: 'number', avaliacao_judicial_data: 'string',
    avaliacao_atualizada_valor: 'number', onus_observacoes: 'string', descricao: 'string', historico_registral: 'string' };
  const props = {}; for (const [k, t] of Object.entries(campos)) props[k] = { type: t };
  props.tipo_documento = { type: 'string', enum: ['edital', 'matricula', 'outro'] };
  props.campos_incertos = { type: 'array', items: { type: 'string' } };
  const schema = { type: 'object', additionalProperties: false, required: Object.keys(props), properties: props };
  const sistema = 'Você lê documentos de imóveis no Brasil (editais de leilão judicial e matrículas do Registro de Imóveis) e extrai dados para um laudo de avaliação. ' +
    'Primeiro identifique o documento em tipo_documento: edital (edital ou aviso de leilão/praça), matricula (certidão de matrícula do Cartório de Registro de Imóveis) ou outro. ' +
    'Se for MATRÍCULA: a descrição do imóvel fica na abertura e as mudanças vêm nos registros (R.) e averbações (Av.) seguintes; use sempre a informação mais recente (novo número do prédio, nova denominação da rua, área retificada, construção averbada). ' +
    'Em onus_observacoes resuma penhoras, hipotecas, alienação fiduciária, indisponibilidades e outros ônus ainda não cancelados, com o número do ato (ex.: R.7 penhora). ' +
    'Em historico_registral resuma em 2 a 5 frases a história registral relevante (aquisições, alienações, ônus e cancelamentos com o número e a data do ato), sem nomes de pessoas físicas. ' +
    'Em descricao transcreva fielmente a descrição do imóvel como consta no documento (na matrícula, o texto que descreve o imóvel, com medidas e confrontações, já atualizado pelas averbações; no edital, a descrição do lote), sem nomes de pessoas físicas. ' +
    'Processo, vara, exequente e valores de avaliação normalmente não existem na matrícula: nesse caso deixe vazio ou 0. ' +
    'Se for EDITAL: extraia também processo, vara, exequente e os valores de avaliação. ' +
    'Copie exatamente o que está escrito; não invente nem deduza valores ausentes. Quando o dado não estiver no documento, use texto vazio ("") ou 0. ' +
    'Áreas em m² como número (49,91 -> 49.91). CEP só com 8 dígitos. andar: ex. "3º e 4º andar". lote_quadra: ex. "lote 29 da quadra 44". cnm: código nacional de matrícula se houver. ' +
    'tipo_imovel: apartamento, casa, sobrado, terreno, comercial, galpao ou rural. exequente = quem pede a execução (autor). Não extraia CPF/CNPJ. ' +
    'Em campos_incertos, liste os nomes dos campos que você preencheu mas que estão pouco legíveis ou ambíguos no documento.';
  const dica = String((entrada.body || {}).tipo_documento || '').toLowerCase();
  const pedido = 'Extraia os dados do imóvel deste documento.' + (['edital', 'matricula'].includes(dica) ? ' O usuário indicou que o documento é: ' + dica + '.' : '');
  const arquivo = ehPdf ? { type: 'file', file: { filename: 'documento.pdf', file_data: 'data:application/pdf;base64,' + b64 } }
                        : { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + b64 } };
  return [{ json: { avaliacaoId, req: { model: 'anthropic/claude-sonnet-5.5', temperature: 0, usage: { include: true },
    response_format: { type: 'json_schema', json_schema: { name: 'documento', strict: true, schema } },
    messages: [ { role: 'system', content: sistema }, { role: 'user', content: [ { type: 'text', text: pedido }, arquivo ] } ] } } }];
} catch (e) {
  await patch({ etapa: 'erro', etapa_erro: String(e.message || e).slice(0, 300) }).catch(() => {});
  throw e;
}

