  const tipo = (txt('tipo_imovel', 30) || '').toLowerCase();
  const base = (['terreno', 'rural'].includes(tipo) ? terreno : null) || priv || total || terreno;
  if (!txt('endereco') || !base) throw new Error('Não encontrei o endereço ou a área ' + nomeDoc + '. Preencha à mão na aba Informações.');
  const cidade = txt('cidade', 80), uf = (txt('uf', 2) || '').toUpperCase() || null, bairro = txt('bairro', 80);
  const tipoCurto = tipo.startsWith('apart') ? 'Apto' : tipo ? tipo[0].toUpperCase() + tipo.slice(1) : 'Imóvel';
  const titulo = [cidade && uf ? cidade + ' (' + uf + ')' : cidade, tipoCurto + ' ' + String(base).replace('.', ',') + 'm²', bairro].filter(Boolean).join(' | ');
  const baixa = Array.isArray(d.campos_incertos) ? d.campos_incertos.slice(0, 30) : [];
  const campos = {
    titulo, endereco: [txt('endereco'), txt('numero', 20), txt('unidade', 60)].filter(Boolean).join(', '),
    bairro, cidade, uf, cep: cep.length === 8 ? cep : null, condominio: txt('condominio', 120), unidade: txt('unidade', 60),
    tipo_imovel: tipo || null, area_privativa_m2: priv, area_total_m2: total, area_terreno_m2: terreno, area_base_calculo_m2: base,
    dormitorios: num('dormitorios', 0, 50), vagas: num('vagas', 0, 50),
    numero_matricula: txt('numero_matricula', 40), cartorio_registro: txt('cartorio_registro', 160),
    numero_processo: txt('numero_processo', 40), tribunal_vara: txt('tribunal_vara', 200), requisitante: txt('exequente', 160),
    extracao: { tipo_documento: d.tipo_documento, campos: d, baixa_confianca: baixa, lido_em: new Date().toISOString(), custo_usd: r.usage && r.usage.cost },
    etapa: 'conferir_dados', etapa_erro: null
  };
  Object.keys(campos).forEach(k => campos[k] === null && delete campos[k]);
  await patch(campos);
  return [{ json: { ok: true, tipo_documento: d.tipo_documento, titulo, baixa_confianca: baixa } }];
} catch (e) {
  await patch({ etapa: 'erro', etapa_erro: String(e.message || e).slice(0, 300) }).catch(() => {});
